mapper.select:
select mn.*,
       sf.T_Name as tName
from Outline_Node_Temp mn
         left join SYS_FileTemplate sf on sf.T_Code = mn.T_Code

    
        and mn.T_Code = #{params.tCode}
    
    
        and sf.T_Name = #{params.tName}
    
    
        and mn.Osl_Id = #{params.oslId}
    
    
        and mn.Create_Uname = #{params.createUname}
    
    
        and mn.Create_Uid = #{params.createUid}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
